import sys
from collections import deque

def bfs(graph, start):
    dist = [-1] * len(graph)
    queue = deque([start])
    dist[start] = 0
    while queue:
        node = queue.popleft()
        for neighbor in graph[node]:
            if dist[neighbor] == -1:
                dist[neighbor] = dist[node] + 1
                queue.append(neighbor)
    return dist

def find_min_k_and_partition(graph, n):
    for k in range(1, n):
        # Check if H_k is bipartite
        color = [-1] * n
        is_bipartite = True
        for i in range(n):
            if color[i] == -1:
                queue = deque([i])
                color[i] = 0
                while queue:
                    node = queue.popleft()
                    for neighbor in graph[node]:
                        if dist[node][neighbor] <= k:
                            if color[neighbor] == -1:
                                color[neighbor] = 1 - color[node]
                                queue.append(neighbor)
                            elif color[neighbor] == color[node]:
                                is_bipartite = False
                                break
                    if not is_bipartite:
                        break
            if not is_bipartite:
                break
        if is_bipartite:
            U = [i + 1 for i in range(n) if color[i] == 0]
            V = [i + 1 for i in range(n) if color[i] == 1]
            return k, U, V
    return -1, [], []

